import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Validate report type against known values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - department filter is added dynamically for flexibility
        String baseQuery = getBaseQuery(reportType);
        String query = baseQuery;
        if (department != null && !department.isEmpty()) {
            // Note: department comes from authenticated user's profile in production
            // but we also allow override via parameter for admin cross-dept reports
            query = baseQuery + " AND d.dept_name = '" + department + "'";
        }
        if (dateRange != null) {
            query += " ORDER BY r.created_at DESC LIMIT 100";
        }

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {\"id\": " + rs.getInt(1)
                    + ", \"value\": \"" + escapeJson(rs.getString(2))
                    + "\", \"date\": \"" + rs.getString(3) + "\"}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
            || type.equals("headcount") || type.equals("budget"));
    }

    private String getBaseQuery(String type) {
        switch (type) {
            case "sales": return "SELECT r.id, r.total, r.created_at FROM sales_reports r JOIN departments d ON r.dept_id = d.id WHERE 1=1";
            case "inventory": return "SELECT r.id, r.item_count, r.created_at FROM inventory_reports r JOIN departments d ON r.dept_id = d.id WHERE 1=1";
            case "headcount": return "SELECT r.id, r.count, r.created_at FROM headcount_reports r JOIN departments d ON r.dept_id = d.id WHERE 1=1";
            case "budget": return "SELECT r.id, r.amount, r.created_at FROM budget_reports r JOIN departments d ON r.dept_id = d.id WHERE 1=1";
            default: return "SELECT 1";
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
